import {LANGUAGES,LAYOUTS,findKey,DEFAULT_SETTINGS,LESSON_GROUPS} from './data.mjs';
import {createProgress,generateWords} from './core.mjs';
import {personalPlan} from './personal-plan.mjs';
import {learningFor,progressFor,dailyPlan,recommendations,chooseTarget,targetWords,contentText,diagnosticText,controlText,validateText,controlSummary,median,backupData,parseBackup,METRICS_VERSION} from './learning.mjs';
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const goals=[['beginner','Начинаю с нуля'],['retrain','Хочу переучиться'],['accuracy','Хочу меньше ошибаться'],['work','Хочу увереннее печатать в работе']];
const names={letters:'Связный текст',shift:'Заглавные и Shift',numbers:'Цифры и знаки',work:'Рабочее сообщение'};
const button=(action,text,klass='outline-button')=>`<button class="${klass}" data-coach="${action}">${text}</button>`;
const round=x=>Number.isFinite(x)?Math.round(x):'—';
export function createCoach(api){
 let draft='',titleDraft='',pendingImport=null,diagnosticStage=0,diagnosticRun=[];
 const state=()=>{let data=api.getData(),settings=data.settings,lang=settings.language,layout=settings.layouts[lang];return{data,settings,lang,layout,model:learningFor(data,lang,layout),progress:progressFor(data,lang,layout)}};
 function routeForm(s){return`<div class="route-form"><label for="coachGoal">Моя цель<select id="coachGoal">${goals.map(([id,name])=>`<option value="${id}" ${s.model.goal===id?'selected':''}>${name}</option>`).join('')}</select></label><label for="coachMinutes">Моя дневная цель<select id="coachMinutes">${[3,5,10].map(n=>`<option value="${n}" ${s.model.minutes===n?'selected':''}>${n} ${n===3?'минуты':'минут'}</option>`).join('')}</select></label>${button('configure',s.model.configured?'Обновить план':'Составить мой план','primary-button')}</div>`}
 function personalMarkup(s){let route=personalPlan(s);return `<section id="personalPlan" class="personal-plan" aria-labelledby="personalPlanTitle"><div class="personal-plan-heading"><div><span class="eyebrow">ТВОЙ ИНДИВИДУАЛЬНЫЙ МАРШРУТ</span><h3 id="personalPlanTitle" tabindex="-1">${esc(route.title)}</h3></div><span class="badge">${LANGUAGES[s.lang].code} · ≈ ${route.minutes} мин / день</span></div><p class="personal-plan-basis">${esc(route.basis)}</p><div class="personal-plan-tasks">${route.tasks.map((task,i)=>`<article><span class="phase-number">${String(i+1).padStart(2,'0')}</span><div><h4>${esc(task.title)}</h4><p>${esc(task.reason)}</p><small>≈ ${task.minutes} ${task.minutes===1?'минута':task.minutes<5?'минуты':'минут'}</small></div>${task.view?`<button class="outline-button" data-view="${task.view}">Начать →</button>`:task.run?`<button class="outline-button" data-coach-run="${task.run}">Начать →</button>`:button(task.coach,'Начать →')}</article>`).join('')}</div><div class="personal-plan-footer"><span>Маршрут уточняется после каждого занятия. Время — ориентир, можно остановиться раньше.</span>${button('diagnostic','Уточнить по диагностике →','soft-button')}</div></section>`}
 async function configurePlan(){
  const goal=document.getElementById('coachGoal').value,minutes=Number(document.getElementById('coachMinutes').value),s=state();
  if(!goals.some(([id])=>id===goal)||![3,5,10].includes(minutes))return;
  s.model.goal=goal;s.model.minutes=minutes;s.model.configured=true;
  if(goal==='beginner')s.settings.speedGoal=Math.min(s.settings.speedGoal,120);
  s.settings.dailyType='time';s.settings.dailyMinutes=minutes;
  const saved=await api.persist();api.render();
  const heading=document.getElementById('personalPlanTitle');heading?.focus({preventScroll:true});document.getElementById('personalPlan')?.scrollIntoView({block:'start',behavior:'instant'});
  api.toast(saved?'План составлен: '+minutes+' минут в день, три конкретных шага.':'План показан, но сохранить его в этом браузере не удалось.');
 }
 function nextLesson(s){for(let g=0;g<LESSON_GROUPS.length;g++)for(let st=0;st<LESSON_GROUPS[g][1];st++)if(!s.progress.lessons[`${s.layout}:${g}:${st}`]?.passed)return[g,st];return[0,0]}
 function diagnosticMarkup(s){let rows=[0,1,2].map(stage=>s.model.diagnostics.findLast(r=>r.contentId===s.lang+'-diagnostic-'+stage)).filter(Boolean);return rows.length?`<section class="diagnostic-summary"><h3>Входной профиль</h3><div class="diagnostic-grid">${rows.map(r=>`<div><span>${r.contentId.endsWith('-2')?'Цифры и знаки':r.contentId.endsWith('-1')?'Заглавные буквы':'Буквы и слова'}</span><b>${round(r.cpm)} CPM</b><small>${round(r.accuracy)}% точности · ${r.corrections||0} исправлений</small></div>`).join('')}</div><p class="storage-note">Это короткие фрагменты разной сложности. По одной попытке нельзя уверенно судить об уровне или росте.</p></section>`:''}
 function planMarkup(){let s=state(),plan=dailyPlan(s.model),target=chooseTarget(s.model,s.lang),check=controlSummary(s.model),diagnosed=new Set(s.model.diagnostics.map(r=>r.contentId)).size>=3,phases=[['warmup','Разминка','Знакомые клавиши в спокойном темпе'],['target','Одна трудность',target.reason],['transfer','Новый контекст','Проверим уверенность в новом связном тексте']],next=phases.find(([id])=>!plan.done[id])?.[0]||'warmup';
  let allDone=Object.values(plan.done).filter(Boolean).length===3;let main=allDone?{title:'Сегодняшний цикл завершён',reason:'Можно остановиться и вернуться позже. Если хочется проверить перенос навыка, выбери новый контрольный текст.',action:'control',cta:'Проверить на новом тексте'}:s.model.goal==='beginner'?{title:'Начни с домашнего ряда',reason:'Уроки постепенно знакомят с клавишами. Здесь важнее уверенные попадания, чем высокая скорость.',action:'lesson',cta:'Продолжить курс'}:!diagnosed?{title:'Узнай, что тренировать дальше',reason:'Три коротких фрагмента: буквы, заглавные, цифры и знаки. Можно сделать паузу или пропустить диагностику.',action:'diagnostic',cta:'Начать диагностику'}:{title:next==='target'&&target.type!=='text'?`Проверим ${target.type==='pair'?'переход':'букву'} «${target.key.toUpperCase()}»`:next==='transfer'?'Навык в новом предложении':next==='warmup'?'Спокойная разминка':'Практика рабочего текста',reason:next==='target'?target.reason:phases.find(p=>p[0]===next)[2],action:'phase-'+next,cta:'Начать следующий шаг'};
  let last=s.model.activities.at(-1),needsReview=last&&Date.now()-last.at>3*86400000;
  return`<section class="welcome"><span class="eyebrow">ТРЕНАЖЁР СЛЕПОЙ ПЕЧАТИ</span><h2>Научись печатать<br>десятью пальцами.</h2><p>Без поиска клавиш и взгляда на клавиатуру. Русский и английский, короткие уроки и практика кода.</p><div class="welcome-actions"><button class="primary-button" data-view="lessons">Начать обучение →</button><button class="outline-button" data-view="practice">Уже умею — практиковаться</button></div><span class="welcome-language">Язык набора: ${LANGUAGES[s.lang].name}. Сменить его можно сверху.</span></section><div class="start-paths"><button data-view="lessons"><span class="path-number">01</span><h3>С нуля</h3><p>Положение пальцев, новые клавиши и игровой маршрут по урокам.</p><b>Открыть уроки →</b></button><button data-view="practice"><span class="path-number">02</span><h3>Стать увереннее</h3><p>Тренируй буквы, точность и ритм. Прогресс сохраняется после каждого задания.</p><b>Начать практику →</b></button><button data-view="code"><span class="path-number">03</span><h3>Печатать код</h3><p>JavaScript, TypeScript, Python, команды и специальные символы.</p><b>Выбрать язык кода →</b></button></div><div class="welcome-how"><strong>Как это работает</strong><span>Выбери раздел</span><i>→</i><span>Набери текст</span><i>→</i><span>Посмотри результат</span></div><details class="home-personal" ${s.model.configured?'open':''}><summary>Индивидуальный план под мою цель</summary>${routeForm(s)}${s.model.configured?personalMarkup(s):`<section class="next-card"><span class="eyebrow">ТВОЙ СЛЕДУЮЩИЙ ШАГ</span><h3>${esc(main.title)}</h3><p>${esc(main.reason)}</p><div class="coach-actions">${button(main.action,main.cta+' →','primary-button')}${button('phase-target','Выбрать практику')}</div></section>`}${needsReview?`<div class="help-tip">После перерыва полезно проверить навык на новом фрагменте. ${button('control','Начать проверку')}</div>`:''}${s.model.configured?'':`<div class="plan-heading"><h3>Цикл на сегодня</h3><span>${Object.values(plan.done).filter(Boolean).length} / 3 шага</span></div><div class="plan-grid">${phases.map(([id,name,reason],i)=>`<section class="plan-card ${plan.done[id]?'done':''}"><span class="phase-number">${plan.done[id]?'✓':String(i+1).padStart(2,'0')}</span><h3>${name}</h3><p>${esc(reason)}</p>${button('phase-'+id,plan.done[id]?'Пройти ещё раз':'Начать →')}</section>`).join('')}</div>`}<section class="control-card"><div><h3>Проверка без заучивания</h3><p>Отдельные тексты, которые не встречаются в обычной практике. Сравниваем только попытки без пауз и подсказок в этом профиле.</p></div>${button('control','Новый контрольный текст')}</section>${check.count?`<div class="control-mini"><span>Независимых попыток: <b>${check.count}</b></span><span>Первый контроль: <b>${round(check.baseline.cpm)} CPM · ${round(check.baseline.accuracy)}%</b></span><span>Последний: <b>${round(check.latest.cpm)} CPM · ${round(check.latest.accuracy)}%</b></span></div>`:''}${diagnosticMarkup(s)}</details><p class="storage-note">План — рекомендация. Его можно менять. По событиям клавиатуры тренажёр не определяет, каким пальцем ты нажал и смотрел ли на клавиши.</p>`;
 }
 function libraryMarkup(){let s=state();return`<div class="coach-intro compact"><div><span class="eyebrow">ПЕРЕНОС В РАБОТУ</span><h2>Твой текст. Твоя практика.</h2><p>Готовые фрагменты или собственный текст. Обработка остаётся в браузере.</p></div></div><div class="text-categories">${Object.entries(names).map(([id,name])=>`<button class="text-category" data-coach-run="${id}"><span>${id==='shift'?'Aa':id==='numbers'?'12:30':id==='work'?'→':'аб'}</span><h3>${name}</h3><p>${id==='numbers'?'Даты, время, суммы и номера':id==='shift'?'Регистр и координация рук':id==='work'?'Письма и обычные сообщения':'Осмысленные предложения'}</p></button>`).join('')}</div><section class="custom-text-card"><h3>Мой текст</h3><label for="libraryDraft">Вставь заметку, документацию или фрагмент кода</label><textarea id="libraryDraft" rows="6" maxlength="5000" placeholder="Текст остаётся на этом устройстве. Переносы строк будут заменены пробелами.">${esc(draft)}</textarea><div class="custom-text-options"><label for="libraryTitle">Название<input id="libraryTitle" maxlength="80" value="${esc(titleDraft)}" placeholder="Например, README или code review"></label><label class="checkbox-label"><input type="checkbox" id="keepCustom">Сохранить в моей библиотеке</label></div><p class="storage-note">До 5000 символов. Копирование идёт по словам; пробелы и переносы нормализуются. Русские буквы ё и е остаются разными.</p><p class="validation-error" id="libraryError" role="alert"></p>${button('custom-start','Тренироваться с моим текстом →','primary-button')}</section>${s.data.library.length?`<section class="library-saved"><h3>На этом устройстве</h3>${s.data.library.map(t=>`<div class="library-item"><div><b>${esc(t.title)}</b><small>${t.text.length} символов · ${LANGUAGES[t.lang]?.name||t.lang}</small></div><button class="outline-button" data-coach-text="${esc(t.id)}">Начать</button><button class="icon-button" data-coach-remove="${esc(t.id)}" aria-label="Убрать ${esc(t.title)}">×</button></div>`).join('')}</section>`:''}<p class="storage-note">Подсказки клавиатуры соответствуют выбранной раскладке. Для символов вне этой схемы воспользуйся своей клавиатурой.</p>`}
 function skillsMarkup(){let s=state(),recs=recommendations(s.model,s.lang),check=controlSummary(s.model),keys=[...LANGUAGES[s.lang].alphabet+'0123456789'];return`<section class="stat-section coach-skills"><h3>Что стоит потренировать</h3>${recs.length?`<div class="recommendations">${recs.map(t=>`<article><b>${esc(t.key.toUpperCase())}</b><p>${t.reason}</p><button class="soft-button" data-coach-target="${esc(t.type+':'+t.key)}">Короткая практика →</button></article>`).join('')}</div>`:'<p class="storage-note">Пока мало повторных наблюдений. Для вывода о букве нужны хотя бы 8 вводов, о переходе — 5. Они собираются во всех новых занятиях.</p>'}<div class="skill-map" aria-label="Наблюдения по клавишам">${keys.map(c=>{let k=s.model.keys[c],n=k?.observations||0,accuracy=n?(1-k.errors/n)*100:null;return`<span class="skill-cell ${n<8?'unknown':accuracy>=97?'reliable':'attention'}" title="${esc(c.toUpperCase())}: ${n} вводов${n?', '+round(accuracy)+'% точности':''}${n<8?' · мало данных':''}">${esc(c.toUpperCase())}<small>${n<8?'·':round(accuracy)+'%'}</small></span>`}).join('')}</div><p class="storage-note">Точки — мало данных. Моторные интервалы исключают исправления и паузы длиннее 2 секунд; время всего занятия сохраняется.</p></section><section class="stat-section"><h3>Контроль на новых текстах</h3>${check.count?`<div class="control-mini"><span>Первый: <b>${round(check.baseline.cpm)} CPM</b></span><span>Последний: <b>${round(check.latest.cpm)} CPM</b></span><span>Точность последнего: <b>${round(check.latest.accuracy)}%</b></span>${check.range?`<span>Последние 3: <b>${round(check.range[0])}–${round(check.range[1])} CPM</b></span>`:''}</div><p class="storage-note">Разные новые тексты одного корпуса. Разница отдельных попыток ещё не доказывает изменение навыка.</p>`:'<p class="storage-note">Здесь появятся завершённые попытки на контрольных текстах без пауз и запросов помощи.</p>'}${button('control','Пройти независимую проверку')}</section>`}
 function dataMarkup(){return`<section class="setting-section"><h3>Мои данные</h3><p class="storage-note">Прогресс, настройки и сохранённые тексты находятся в этом браузере. Резервная копия позволяет перенести их на другое устройство.</p><div class="coach-actions data-actions">${button('export','Скачать резервную копию')}<label class="outline-button file-button" tabindex="0" role="button">Загрузить копию<input id="backupFile" type="file" accept="application/json,.json"></label>${button('reset','Очистить данные','danger-button')}${localStorage.getItem('ten-fingers-undo')?button('undo','Восстановить предыдущие данные'):''}</div>${api.getData().trash?.length?button('restore-texts','Вернуть убранные тексты','soft-button'):''}${button('metrics','Как считаются показатели','soft-button')}</section>`}
 function start(words,ctx){api.startActivity(words,ctx)}
 function runType(type,phase){let s=state(),text=contentText(s.lang,type,s.model.activities.length);let result=validateText(text,s.layout);start(result.words,{activity:type,title:names[type],phase,reason:type==='numbers'?'Практика цифрового ряда и знаков. Внимательно прочитай фрагмент перед началом.':'Новый контекст для привычных клавиш.',contentId:s.lang+'-'+type+'-'+s.model.activities.length})}
 function startPhase(phase){let s=state();if(phase==='warmup'){let letters=s.model.goal==='beginner'?LANGUAGES[s.lang].alphabet.slice(0,s.progress.unlocked):LANGUAGES[s.lang].alphabet;start(generateWords({lang:s.lang,letters,count:12}),{activity:'warmup',phase,title:'Спокойная разминка',reason:'Знакомые слова. Найди удобный темп, без гонки за рекордом.'})}else if(phase==='target'){let target=chooseTarget(s.model,s.lang);let chars=s.model.goal==='beginner'?LANGUAGES[s.lang].alphabet.slice(0,s.progress.unlocked):LANGUAGES[s.lang].alphabet;let words=s.model.goal==='beginner'&&target.type==='text'?generateWords({lang:s.lang,letters:chars,count:20}):targetWords(s.lang,target,20,chars);start(words,{activity:'target',phase,title:target.type==='text'?(names[target.key]||'Практика рабочего текста'):`Практика ${target.type==='pair'?'перехода':'буквы'} «${target.key.toUpperCase()}»`,reason:target.reason,target:target.type+':'+target.key})}else if(s.model.goal==='beginner'&&s.progress.unlocked<LANGUAGES[s.lang].alphabet.length)start(generateWords({lang:s.lang,letters:LANGUAGES[s.lang].alphabet.slice(0,s.progress.unlocked),count:15}),{activity:'transfer',phase:'transfer',title:'Знакомые клавиши в новых словах',reason:'Связный текст появится по мере освоения алфавита. Сейчас закрепим доступные буквы в разных словах.'});else runType('work','transfer')}
 function startDiagnostic(stage=0){let s=state();diagnosticStage=stage;if(stage===0)diagnosticRun=[];let words=diagnosticText(s.lang,stage).split(' ');start(words,{activity:'diagnostic',diagnosticStage:stage,title:`Диагностика · ${stage+1} / 3`,reason:['Обычные буквы и слова. Печатай в удобном темпе.','Заглавные буквы. Подсказка Shift показывает рекомендуемую руку.','Даты, время и знаки. Это отдельная часть рабочего навыка.'][stage],contentId:s.lang+'-diagnostic-'+stage})}
 function startControl(){let s=state(),c=controlText(s.model,s.lang);if(!c){api.openDialog('Все новые проверки пройдены','<p class="help-copy">В текущем корпусе больше нет незнакомых контрольных текстов. Можно продолжать обычную практику; повтор знакомого текста не будет отмечен как независимая проверка.</p>');return}start(c.text.split(' '),{activity:'control',title:'Независимая проверка',reason:'Этот текст не встречался в обучении. Помощь скрыта; F1 покажет её по запросу. Попытки с паузой или помощью сохранятся, но не войдут в сравнение.',hideHints:true,strictTest:true,contentId:c.id})}
 function resultExtra(result,ctx){let observation=result.accuracy<90?'Сейчас полезнее спокойный темп и короткая коррекция ошибок.':result.hints>2?'В этой попытке помощь пригодилась несколько раз. Следующую можно попробовать с подсказкой по запросу.':result.corrections>3?'Финальный текст может быть точным после исправлений. Попробуем уменьшить число лишних действий.':'Проверим этот навык в другом контексте.';
  if(ctx.activity==='diagnostic'){diagnosticRun[ctx.diagnosticStage]=result;return`<div class="result-coach"><p>${observation}</p>${ctx.diagnosticStage<2?button('diagnostic-next','Следующий фрагмент →','primary-button'):button('back-plan','Посмотреть мой план →','primary-button')}</div>`}
  return`<div class="result-coach"><span class="eyebrow">СЛЕДУЮЩИЙ ШАГ</span><p>${observation}</p>${ctx.phase==='warmup'?button('phase-target','Перейти к основной практике →','primary-button'):ctx.phase==='target'?button('phase-transfer','Проверить в связном тексте →','primary-button'):button('back-plan','Вернуться к моему плану →','primary-button')}</div>`;
 }
 function metricsDialog(){api.openDialog('Показатели без скрытых штрафов',`<div class="help-copy"><p><b>CPM</b> — правильные символы конечного текста за активную минуту. Включены пробелы между введёнными словами, знаки и цифры. Финальный пробел не учитывается. <b>WPM = CPM ÷ 5.</b></p><p><b>Точность ввода</b> — доля правильных вставленных символов среди всех вставок. Удалённая опечатка остаётся в этом числе. Повторная ошибка считается новой попыткой. Управляющие клавиши и пробел перехода не входят в точность букв.</p><p><b>С первого раза</b> — доля позиций, куда первый символ попал верно. <b>Точность финала</b> учитывает выравнивание с эталоном: одна вставка не превращает всё слово в цепочку ошибок.</p><p><b>Исправления</b> — операции удаления или замены. Время исправлений измеряется от начала удаления до следующего правильного ввода, когда эту связь можно установить.</p><p>Практика разрешает паузу. Тесты и контроль с паузой сохраняются как учебные попытки и исключаются из рекордов и независимого сравнения. Таймер начинается с первого принятого символа.</p><p>Новая версия метрик: ${METRICS_VERSION}. Старые результаты сохраняются со своими исходными числами; сравнение роста строится по новым контрольным попыткам.</p></div>`)}
 function rememberUndo(){localStorage.setItem('ten-fingers-undo',JSON.stringify(api.getData()))}
 function downloadBackup(){let blob=new Blob([backupData(api.getData())],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ten-fingers-progress-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function handleClick(b){let action=b.dataset.coach,s=state();if(b.dataset.coachRun){runType(b.dataset.coachRun);return true}if(b.dataset.coachTarget){let [type,key]=b.dataset.coachTarget.split(':'),target=recommendations(s.model,s.lang).find(t=>t.type===type&&t.key===key);if(target)start(targetWords(s.lang,target),{activity:'target',title:`Практика «${key}»`,reason:target.reason,target:type+':'+key});return true}if(b.dataset.coachText){let text=s.data.library.find(t=>t.id===b.dataset.coachText);if(text){start(validateText(text.text,s.layout).words,{activity:'custom',title:text.title,reason:'Твой материал. При необходимости переключай язык ввода.',contentId:text.id})}return true}if(b.dataset.coachRemove){s.data.trash??=[];let index=s.data.library.findIndex(t=>t.id===b.dataset.coachRemove);if(index>=0)s.data.trash.push(s.data.library.splice(index,1)[0]);api.persist();api.render();api.toast('Текст убран. Его можно вернуть из настроек данных.');return true}if(!action)return false;
  if(action.startsWith('phase-')){startPhase(action.slice(6));return true}
  switch(action){case'configure':configurePlan().catch(()=>api.toast('Не удалось составить план. Попробуй ещё раз.'));break;
   case'lesson':api.startLesson(...nextLesson(s));break;case'diagnostic':startDiagnostic();break;case'diagnostic-next':startDiagnostic(diagnosticStage+1);break;case'control':startControl();break;case'back-plan':api.navigate('plan');break;
   case'custom-start':{draft=document.getElementById('libraryDraft').value;titleDraft=document.getElementById('libraryTitle').value.trim();let result=validateText(draft,s.layout),error=document.getElementById('libraryError');if(result.text.length<3){error.textContent='Добавь хотя бы несколько символов.';break}if(result.words.some(w=>w.length>80)){error.textContent='Слово длиннее 80 символов. Раздели длинную ссылку или строку пробелами.';break}if(/[\u200b-\u200f\u202a-\u202e\u2060\u2066-\u2069]/u.test(result.text)){error.textContent='В тексте есть невидимые символы. Убери скрытые разделители и знаки направления текста, затем повтори.';break}if(result.unsupported.some(c=>/[^\x20-\x7e\u0400-\u04ff\u00c0-\u024f]/u.test(c))){error.textContent='В этом режиме поддерживаются буквы, цифры и обычные знаки. Убери эмодзи и сложные составные символы.';break}let id='local-'+Date.now();if(document.getElementById('keepCustom').checked){s.data.library.push({id,title:titleDraft||'Мой текст',text:result.text,lang:s.lang,at:Date.now()});api.persist()}start(result.words,{activity:'custom',title:titleDraft||'Мой текст',reason:'Текст обработан локально. Повторы пробелов и переносы строк заменены одним пробелом.',contentId:id});break}
   case'restore-texts':s.data.library.push(...(s.data.trash||[]));s.data.trash=[];api.persist();api.render();break;case'export':downloadBackup();break;case'metrics':metricsDialog();break;
   case'import-confirm':if(pendingImport){rememberUndo();api.replaceData(pendingImport);pendingImport=null;document.getElementById('dialog').close();api.navigate('plan');api.toast('Копия восстановлена. Предыдущие данные можно вернуть в настройках.')}break;
   case'reset':api.openDialog('Очистить данные этого браузера?',`<div class="help-copy"><p>Будут сброшены прогресс, настройки и библиотека. Предыдущая версия останется доступна через кнопку восстановления в этом браузере.</p></div><div class="coach-actions">${button('export','Сначала скачать копию')}${button('reset-confirm','Сбросить с возможностью восстановления','danger-button')}</div>`);break;
   case'reset-confirm':rememberUndo();api.replaceData({version:2,settings:structuredClone(DEFAULT_SETTINGS),progress:Object.fromEntries(Object.keys(LANGUAGES).map(l=>[l,createProgress()])),legacyLessons:{},guideSeen:false});document.getElementById('dialog').close();api.navigate('plan');break;
   case'undo':{let raw=localStorage.getItem('ten-fingers-undo');if(raw){let previous=JSON.parse(raw);rememberUndo();api.replaceData(previous);api.navigate('plan');api.toast('Предыдущие данные восстановлены.')}break}
  }return true;
 }
 async function handleChange(el){if(el.id!=='backupFile')return false;try{let file=el.files?.[0];if(!file)return true;if(file.size>15000000)throw new Error('Файл слишком большой.');pendingImport=parseBackup(await file.text());let count=Object.values(pendingImport.learning||{}).reduce((sum,m)=>sum+m.activities.length,0);api.openDialog('Восстановить резервную копию?',`<div class="help-copy"><p>В копии ${count} новых занятий и ${pendingImport.library?.length||0} сохранённых текстов. Текущие данные будут заменены; их можно вернуть через восстановление в настройках.</p></div>${button('import-confirm','Восстановить копию','primary-button')}`)}catch(e){api.toast(e.message);el.value=''}return true}
 function rememberDraft(el){if(el.id==='libraryDraft')draft=el.value;if(el.id==='libraryTitle')titleDraft=el.value}
 return{planMarkup,libraryMarkup,skillsMarkup,dataMarkup,resultExtra,handleClick,handleChange,rememberDraft,metricsDialog,startPhase};
}
